# -*- coding: utf-8 -*-
"""
BÀI SÁP NHẬP V3 - XEM TRƯỚC TÁC ĐỘNG VÀ KHÓA QUY TẮC CHUYỂN DỮ LIỆU

- Chỉ cài trên Bài SÁP NHẬP V2 đúng phiên bản đã kiểm thử.
- KHÔNG ghi dữ liệu nghiệp vụ vào phocap.db.
- Mở nút XEM TRƯỚC TÁC ĐỘNG cho phương án MAPPED khớp đủ DB.
- Mô phỏng trên bản sao SQLite trong RAM; THỰC HIỆN SÁP NHẬP vẫn khóa backend.
"""
from __future__ import annotations

import base64
import hashlib
import importlib
import os
import py_compile
import shutil
import sys
from datetime import datetime
from pathlib import Path

EXPECTED_V2 = {'app/routers/school_merger.py': '1a92a8f91f5861ffdda74a8e3631921a4fdcb7becaab3b85ab7f5f3c858ecb28',
 'app/templates/data_tools/school_merger.html': 'f398412623b9d6f3934d3344e05d11a061548ae899f9abe2b990e3fabd26fc22',
 'app/templates/data_tools/school_merger_plans.html': '359a7308b898437ad53c3413adedb9fbd531ae892228068ae641ea6c66349686'}
EXPECTED_V3 = {'app/routers/school_merger.py': '08cf950257a0fe67b0ea249ff5da7d27fa0af15915ddc2194a05389aa5952d63',
 'app/services/school_merger_preview_service.py': '4d40be778f089f095075b6ea38426d201823752293e5aac454b834a98be60c46',
 'app/templates/data_tools/school_merger.html': '7d0c4c11f5b28c64f6f2c709cfdef4df91e1ad36cf971a2e895978b959477c37',
 'app/templates/data_tools/school_merger_plans.html': 'f1397bc727b86ed98eda75ef64c81d42873c83ee5cf55bd56732ddeeca69b9d7',
 'app/templates/data_tools/school_merger_preview.html': 'ab0fdb101c6bda90be22a88d940ff6596a710e47c117ae2c7dfd671825a31183'}
DEPENDENCY_HASHES = {'app/services/school_merger_official_registry.py': '8ce1f5f045737c57511a401d49a5fa264b8166b9f84c4063f0af26647505f656',
 'app/services/school_merger_service.py': '414fb49a4c5f4fed7b571cc55df381678fe660cd8a675ecaa2f6fd70ebd7827a',
 'data/school_merger_official_registry.json': 'f58969c363d9ec81739a9ee2be9d982b542e602c545f17fdc9c2ddcf397eca6a'}
EMBEDDED_FILES = {'app/routers/school_merger.py': '',
 'app/services/school_merger_preview_service.py': '',
 'app/templates/data_tools/school_merger.html': '',
 'app/templates/data_tools/school_merger_plans.html': '',
 'app/templates/data_tools/school_merger_preview.html': ''}


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def fail(message: str) -> None:
    print("\n" + "=" * 88)
    print("DỪNG AN TOÀN")
    print(message)
    print("Không có thay đổi nào được ghi vào database.")
    print("=" * 88)
    raise SystemExit(1)


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + ".v3_tmp")
    temp.write_bytes(data)
    os.replace(temp, path)


def main() -> None:
    root = Path(__file__).resolve().parent
    db = root / "data" / "phocap.db"
    print("=" * 88)
    print("BÀI SÁP NHẬP V3 - XEM TRƯỚC TÁC ĐỘNG")
    print(f"Dự án: {root}")
    print("Cam kết: chỉ mô phỏng; THỰC HIỆN SÁP NHẬP vẫn khóa; không ghi phocap.db.")
    print("=" * 88)

    if not (root / "app").is_dir() or not db.exists():
        fail("Hãy chép bộ cài vào đúng thư mục gốc C:\\PhoCap rồi chạy lại.")

    # Khóa đúng engine và sổ phương án đã dùng để kiểm thử V3.
    for rel, expected in DEPENDENCY_HASHES.items():
        path = root / rel
        if not path.exists():
            fail(f"Thiếu tệp nền bắt buộc: {rel}")
        got = sha256_file(path)
        if got != expected:
            fail(
                f"Tệp nền {rel} khác phiên bản đã kiểm thử.\n"
                f"SHA hiện tại: {got}\nSHA cần có: {expected}"
            )

    # Các tệp V2 được phép ở đúng V2 hoặc đã là V3 khi chạy lại.
    for rel in EXPECTED_V3:
        path = root / rel
        if path.exists():
            got = sha256_file(path)
            allowed = {EXPECTED_V3[rel]}
            if rel in EXPECTED_V2:
                allowed.add(EXPECTED_V2[rel])
            if got not in allowed:
                fail(
                    f"Tệp {rel} đã bị thay đổi ngoài Bài V2/V3 nên bộ cài không tự ghi đè.\n"
                    f"SHA hiện tại: {got}"
                )
        elif rel in EXPECTED_V2:
            fail(f"Thiếu tệp V2 bắt buộc: {rel}")

    db_before = sha256_file(db)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = root / "backups" / f"backup_truoc_bai_sap_nhap_v3_{stamp}"
    backup_dir.mkdir(parents=True, exist_ok=False)

    for rel in EXPECTED_V3:
        src = root / rel
        if src.exists():
            dst = backup_dir / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

    try:
        for rel, encoded in EMBEDDED_FILES.items():
            atomic_write(root / rel, base64.b64decode(encoded))

        for rel, expected in EXPECTED_V3.items():
            got = sha256_file(root / rel)
            if got != expected:
                raise RuntimeError(f"SHA sau cài không đúng ở {rel}: {got}")

        py_compile.compile(str(root / "app" / "routers" / "school_merger.py"), doraise=True)
        py_compile.compile(str(root / "app" / "services" / "school_merger_preview_service.py"), doraise=True)

        sys.path.insert(0, str(root))
        importlib.invalidate_caches()
        from app.services.school_merger_official_registry import list_official_registry_plans
        from app.services.school_merger_preview_service import build_official_plan_impact_preview

        cua_lo = [
            p for p in list_official_registry_plans(level_code="TH")
            if p.get("commune_excel") == "Cửa Lò"
        ]
        if len(cua_lo) != 4:
            raise RuntimeError(f"Cửa Lò - Tiểu học phải có 4 nhóm, hiện có {len(cua_lo)}.")

        mapped = [p for p in cua_lo if str(p.get("action_type") or "").upper() == "MAPPED"]
        if len(mapped) != 3:
            raise RuntimeError(f"Cửa Lò - Tiểu học phải có 3 nhóm nguồn→đích, hiện có {len(mapped)}.")

        preview_lines = []
        for plan in mapped:
            preview = build_official_plan_impact_preview(str(plan["id"]))
            if preview.get("blockers"):
                raise RuntimeError(
                    f"Phương án {plan['id']} bị chặn khi mô phỏng: "
                    + " | ".join(preview.get("blockers") or [])
                )
            if not preview.get("simulation_ok"):
                raise RuntimeError(f"Phương án {plan['id']} chưa vượt qua mô phỏng RAM.")
            src_names = ", ".join(
                str(x.get("name") or x.get("excel_name") or "")
                for x in preview.get("source_schools") or []
            )
            dst_name = str((preview.get("target_school") or {}).get("name") or "")
            summary = preview.get("summary") or {}
            preview_lines.append(
                f" - {src_names} -> {dst_name}: mô phỏng ĐẠT; "
                f"current/future={summary.get('direct_move_rows', 0)}; "
                f"giữ lịch sử={summary.get('historical_preserve_rows', 0)}; "
                f"rollover đội ngũ={summary.get('staff_rollover_candidates', 0)}"
            )

        router_text = (root / "app" / "routers" / "school_merger.py").read_text(encoding="utf-8")
        if "Chức năng THỰC HIỆN SÁP NHẬP chưa được mở trong Bài SÁP NHẬP V2" not in router_text:
            raise RuntimeError("Không còn nhận diện được khóa backend THỰC HIỆN SÁP NHẬP.")
        if '@router.get("/phuong-an/xem-truoc/{plan_id}"' not in router_text:
            raise RuntimeError("Chưa cài route XEM TRƯỚC TÁC ĐỘNG V3.")

        db_after = sha256_file(db)
        if db_before != db_after:
            raise RuntimeError("SHA256 phocap.db đã thay đổi trong quá trình cài/kiểm thử V3.")

    except Exception as exc:
        for rel in EXPECTED_V3:
            backup = backup_dir / rel
            dest = root / rel
            if backup.exists():
                dest.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(backup, dest)
            elif rel not in EXPECTED_V2 and dest.exists():
                try:
                    dest.unlink()
                except Exception:
                    pass
        fail("Cài đặt/kiểm thử V3 thất bại và mã nguồn đã được hoàn tác: " + str(exc))

    report = [
        "BÀI SÁP NHẬP V3 - CÀI ĐẶT THÀNH CÔNG",
        f"Thời gian: {datetime.now().isoformat(timespec='seconds')}",
        f"Dự án: {root}",
        f"Backup mã nguồn: {backup_dir}",
        "",
        "TỆP ĐÃ CÀI:",
        *[f" - {rel}" for rel in EXPECTED_V3],
        "",
        "KIỂM TRA AN TOÀN:",
        " - Database SHA256 trước/sau: KHÔNG THAY ĐỔI.",
        " - THỰC HIỆN SÁP NHẬP: VẪN KHÓA ở backend.",
        " - V3 chỉ mô phỏng trên bản sao SQLite trong RAM.",
        " - Cửa Lò - Tiểu học: 4 nhóm; 3 nhóm nguồn→đích đều mô phỏng ĐẠT.",
        "",
        "CHI TIẾT CỬA LÒ - TIỂU HỌC:",
        *preview_lines,
        "",
        "BƯỚC KIỂM TRA GIAO DIỆN:",
        " 1) Khởi động lại Uvicorn.",
        " 2) Mở Sáp nhập trường -> Danh sách phương án chính thức.",
        " 3) Chọn 2026-2027 -> Cửa Lò -> Tiểu học.",
        " 4) Tại Nghi Hoà -> Nghi Hải, bấm XEM TRƯỚC TÁC ĐỘNG.",
        " 5) Phải thấy school_id nguồn/đích, số dòng chuyển/giữ và MÔ PHỎNG ĐẠT.",
        " 6) Không được có nút THỰC HIỆN SÁP NHẬP đang hoạt động.",
    ]
    report_path = root / f"bao_cao_cai_bai_sap_nhap_v3_{stamp}.txt"
    report_path.write_text("\n".join(report) + "\n", encoding="utf-8")

    print("\n" + "\n".join(report))


if __name__ == "__main__":
    main()
